{
  "meta": {
    "title": "收并购中的控制权争夺分析",
    "title_en": "Analysis of control disputes in mergers and acquisitions",
    "author": "王智旸",
    "author_en": "WANG Zhiyang",
    "supervisor": "黄张凯  副教授",
    "supervisor_en": "",
